import { chromium } from "playwright";

const b = await chromium.launch();
const page = await b.newPage();
const errors = [];
page.on("pageerror", (e) => errors.push(String(e)));

await page.goto("http://127.0.0.1:4000/", { waitUntil: "networkidle" });
await page.waitForSelector('body[data-harness-ready="true"]', { timeout: 5000 });

// Create a bookmark through the UI
await page.click("#new-btn");
await page.fill("#f-url", "developer.mozilla.org");
await page.fill("#f-title", "MDN Web Docs");
await page.fill("#f-tags", "reference, web");
await page.click("#form button[type=submit]");
await page.waitForSelector(".card");

const cards = await page.$$eval(".card", (els) => els.length);
const tagChips = await page.$$eval(".tag-chip", (els) => els.length);
const ready = await page.getAttribute("body", "data-harness-ready");

console.log(JSON.stringify({ ready, cards, tagChips, pageErrors: errors }, null, 2));
await b.close();

